class Solution {
public:
    string originalDigits(string s) {
        int cnt[26] = {0};
        for (char c : s) cnt[c - 'a']++;

        int digit[10];
        digit[0] = cnt['z' - 'a'];
        digit[2] = cnt['w' - 'a'];
        digit[4] = cnt['u' - 'a'];
        digit[6] = cnt['x' - 'a'];
        digit[8] = cnt['g' - 'a'];
        digit[3] = cnt['h' - 'a'] - digit[8];
        digit[5] = cnt['f' - 'a'] - digit[4];
        digit[7] = cnt['s' - 'a'] - digit[6];
        digit[9] = cnt['i' - 'a'] - digit[5] - digit[6] - digit[8];
        digit[1] = cnt['n' - 'a'] - digit[7] - 2 * digit[9];

        string result;
        for (int d = 0; d <= 9; d++) {
            for (int i = 0; i < digit[d]; i++) {
                result += ('0' + d);
            }
        }
        return result;
    }
};
